import{_ as a,o as t,c as i,aw as r}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Микросервисы","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/concepts/microservices.md","filePath":"wiki/dev-commit/theory/architecture/concepts/microservices.md"}'),o={name:"wiki/dev-commit/theory/architecture/concepts/microservices.md"};function c(l,e,s,n,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="микросервисы" tabindex="-1">Микросервисы <a class="header-anchor" href="#микросервисы" aria-label="Permalink to &quot;Микросервисы&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Микросервисы</strong> - разбивают приложения на более мелкие автономные сервисы, которые взаимодействуют друг с другом</li></ul></div><h2 id="плюсы-и-минусы" tabindex="-1">Плюсы и минусы <a class="header-anchor" href="#плюсы-и-минусы" aria-label="Permalink to &quot;Плюсы и минусы&quot;">​</a></h2><h3 id="плюсы" tabindex="-1">Плюсы <a class="header-anchor" href="#плюсы" aria-label="Permalink to &quot;Плюсы&quot;">​</a></h3><ul><li>Масштабируемость и гибкость. Каждый микросервис можно масштабировать независимо от других, исходя от его конкретных потребностей. Такая детализированная масштабируемость позволяет эффективно распределять ресурсы и обеспечивает оптимальную производительность</li><li>Технологическое разнообразие и автономия. Каждый сервис работает обособленно, так что можно подобрать для него разные технологии и фреймворки – если только их интерфейсы не зависят от технологий</li><li>Деплой и тестирование. Сервисы не имеют привязки друг к другу, благодаря чему их можно разрабатывать, тестировать и развертывать обособленно. Это сокращает срок вывода на рынок, ведь новые функции и обновления можно развертывать без изменения всего приложения</li></ul><h3 id="минусы" tabindex="-1">Минусы <a class="header-anchor" href="#минусы" aria-label="Permalink to &quot;Минусы&quot;">​</a></h3><ul><li>Сложности с управлением распределенной системой. Для координации взаимодействия между сервисами, обеспечения согласованности данных и обработки сбоев необходимо сложное проектирование и внедрение</li><li>Координация и взаимодействие процессов. Чем больше сервисов становится, тем сложнее поддерживать их взаимодействие и согласованность данных</li></ul>',7)])])}const _=a(o,[["render",c]]);export{u as __pageData,_ as default};
